from pathlib import Path
import json
subject = 'site:shopify-catalogue-example'
digest = 'b5192231bdfa03f011ea45273891c67b883b7c0a4f4d2bef75f7b22e684aa711'
path = Path('world/pages/reviews-1.json')
if not path.is_file():
    print('Review page unavailable in EXEC inputs')
else:
    page = json.loads(path.read_text(encoding='utf-8'))
    def records(value):
        if isinstance(value, dict):
            if value.get('subject') == subject and value.get('digest') == digest:
                yield {key: value.get(key) for key in ('subject', 'digest', 'verdict', 'seq', 'host_provider', 'host_turn')}
            for child in value.values():
                yield from records(child)
        elif isinstance(value, list):
            for child in value:
                yield from records(child)
    print(json.dumps(list(records(page))))
